      <button onclick="startCoinCatcher()" class="sf-btn gold">Play Now</button>
    </div>
    <script>
      function startCoinCatcher() {
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        let score = 0;
        let basketX = canvas.width/2 - 30;
        let gameOver = false;

        // Game objects
        const coins = [];
        const bombs = [];

        // Controls
        canvas.addEventListener('mousemove', (e) => {
          basketX = e.clientX - canvas.offsetLeft - 30;
          if (basketX < 0) basketX = 0;
          if (basketX > canvas.width - 60) basketX = canvas.width - 60;
        });

        // Game loop
        function update() {
          if (gameOver) return;

          // Clear
          ctx.clearRect(0, 0, canvas.width, canvas.height);

          // Draw basket
          ctx.fillStyle = '#f1c40f';
          ctx.fillRect(basketX, canvas.height - 30, 60, 20);

          // Spawn objects
          if (Math.random() < 0.03) {
            coins.push({
              x: Math.random() * (canvas.width - 20),
              y: 0,
              speed: 2 + Math.random() * 3
            });
          }

          if (Math.random() < 0.01) {
            bombs.push({
              x: Math.random() * (canvas.width - 20),
              y: 0,
              speed: 3 + Math.random() * 2
            });
          }

          // Update coins
          for (let i = coins.length - 1; i >= 0; i--) {
            const coin = coins[i];
            ctx.fillStyle = '#f1c40f';
            ctx.beginPath();
            ctx.arc(coin.x + 10, coin.y + 10, 10, 0, Math.PI * 2);
            ctx.fill();

            coin.y += coin.speed;

            // Collision
            if (coin.y + 20 > canvas.height - 30 && 
                coin.x > basketX && coin.x < basketX + 60) {
              score += 10;
              document.getElementById('score').textContent = score;
              coins.splice(i, 1);
              FactorySound.coin();
              continue;
            }

            // Out of bounds
            if (coin.y > canvas.height) {
              coins.splice(i, 1);
            }
          }

          // Update bombs
          for (let i = bombs.length - 1; i >= 0; i--) {
            const bomb = bombs[i];
            ctx.fillStyle = '#e74c3c';
            ctx.beginPath();
            ctx.arc(bomb.x + 10, bomb.y + 10, 10, 0, Math.PI * 2);
            ctx.fill();

            bomb.y += bomb.speed;

            // Collision
            if (bomb.y + 20 > canvas.height - 30 && 
