              gameOver = true;
              bombs.splice(i, 1);
              FactorySound.error();
              setTimeout(() => {
                FactoryPro.scoreToken(score);
                FactoryNav.back();
              }, 1000);
              continue;
            }

            // Out of bounds
            if (bomb.y > canvas.height) {
              bombs.splice(i, 1);
            }
          }

          requestAnimationFrame(update);
        }

        // Timer
        setTimeout(() => {
          gameOver = true;
          FactoryPro.scoreToken(score);
          FactoryNav.back();
        }, 20000);

        update();
      }
