      function spinWheel() {
        const canvas = document.getElementById('wheelCanvas');
        const ctx = canvas.getContext('2d');
        const prizes = [10, 20, 30, 40, 50, 100];
        let spinning = false;

        function drawWheel(angle = 0) {
          ctx.clearRect(0, 0, canvas.width, canvas.height);

          const centerX = canvas.width / 2;
          const centerY = canvas.height / 2;
          const radius = 140;

          // Draw segments
          for (let i = 0; i < 6; i++) {
            ctx.beginPath();
            ctx.moveTo(centerX, centerY);
            ctx.arc(centerX, centerY, radius, 
                    angle + (i * Math.PI/3), 
                    angle + ((i+1) * Math.PI/3), false);
            ctx.closePath();
            ctx.fillStyle = ['#e74c3c', '#f1c40f', '#3498db', '#2ecc71', '#9b59b6', '#1abc9c'][i];
            ctx.fill();

            // Text
            ctx.save();
            ctx.translate(centerX, centerY);
            ctx.rotate(angle + (i * Math.PI/3) + Math.PI/6);
            ctx.fillStyle = 'white';
            ctx.font = 'bold 16px Arial';
            ctx.fillText(prizes[i] + ' Coins', radius/2, 10);
            ctx.restore();
          }
        }

        function spinWheel() {
          if (spinning) return;
          spinning = true;

          let spinAngle = 0;
          const spinTime = 3000;
          const startTime = Date.now();

          function animate() {
            const elapsed = Date.now() - startTime;
            const progress = Math.min(elapsed / spinTime, 1);
            const easeProgress = 1 - Math.pow(1 - progress, 3);

            spinAngle = easeProgress * 10 * Math.PI;
            drawWheel(spinAngle);

            if (progress < 1) {
              requestAnimationFrame(animate);
            } else {
              spinning = false;
              const prizeIndex = 5 - Math.floor((spinAngle % (2 * Math.PI)) / (Math.PI / 3));
